parameters.jsCode:
const spec = $('Architect').first().json.output;
const definition = $('Writer').first().json.output;
const review = $('Critic').first().json.output;

const shipIt = /SHIP IT/i.test(review);
const blockers = (review.match(/BLOCKER/gi) || []).length;

// The hub speaks this aloud, so keep the summary to something sayable.
const summary = shipIt
  ? `Built it. The critic passed it with no blockers.`
  : `Built it, but the critic found ${blockers} blocker${blockers === 1 ? '' : 's'}. Full review is in the transcript.`;

return [{ json: { summary, shipIt, blockers, spec, definition, review } }];
